UPDATE destinations SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Prag","country":"Tschechien","city":"Prag","description":"Die Stadt der hundert Türme trägt noch einen zweiten, weniger offiziellen Titel: Europas JGA-Hauptstadt. Prag packt alles, was ein Gruppenwochenende braucht, in eine fußläufige, biergetränkte Stadt — weltberühmtes tschechisches Pils zu Preisen, die sich immer noch wie ein Druckfehler anfühlen, eine mittelalterliche Altstadt, die auf jedem Foto spektakulär aussieht, und ein Nachtleben, das bis zum Sonnenaufgang läuft. Trivlus Prag-Katalog umfasst mehr als 70 Aktivitäten aus Schießen, Extremsport, tschechischer Bierkultur, Essen und Trinken, Chillout-Sessions zum Regenerieren, Nachtleben und Pranks: eine AK-47 abfeuern, im BMP-1 mitfahren, Wildwasser raften, im Bier-Spa entspannen, beim mittelalterlichen Bankett schlemmen oder über die Moldau schippern — bei den meisten Buchungen übernehmen Trivlu-Guides und Transport die Logistik. Baut das Programm um den Bräutigam herum, haltet Adrenalin und Erholung im Gleichgewicht und lasst Prag tun, was Prag am besten kann."}}'::jsonb)::text WHERE slug = 'prague';
