UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Bananenboot","description":"Genießt eine adrenalingeladene Bananenboot-Fahrt vor der Küste Teneriffas, bei der ihr hinter einem starken Motorboot über die Wellen hüpft, spritzt und rast. Diese spaßige Gruppenaktivität ist perfekt für Familien und Freunde, die ein aufregendes und unvergessliches Abenteuer auf dem Meer suchen.","includes":"Sicherheitseinweisung; Schwimmweste; Versicherung; Bananenboot-Fahrt (10 Minuten); Begleitboot; Betreuung durch Instruktor"}}'::jsonb)::text WHERE slug = 'banana-boat';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Buggy-Safari","description":"Erlebt eine aufregende Buggy-Safari durch die Vulkanlandschaften Teneriffas mit einer spannenden Fahrt Richtung Teide oder einer malerischen Sonnenuntergangstour. Dieses Offroad-Erlebnis verbindet Adrenalin, atemberaubende Ausblicke und unvergessliche Stopps entlang der bekanntesten Routen der Insel. Buggy-Kapazität: 2 / 4 / 6 Sitze (140 EUR / 240 EUR / 340 EUR pro Buggy)","includes":"Buggy-Miete; Geführte Tour; Kraftstoff; Sicherheitseinweisung; Stopp am Teide / an Aussichtspunkten; Instruktor-Guide. Fahrer braucht gültigen Führerschein; Optionen: Tagestour zum Teide oder Sonnenuntergangstour."}}'::jsonb)::text WHERE slug = 'buggy-safari';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Mietwagen","description":"Mietet ein Auto auf Teneriffa zu günstigen Tagespreisen mit bequemer Lieferung ans Hotel — eine große Fahrzeugauswahl für alle Reisebedürfnisse.","includes":"Lieferung ans Hotel; Keine Kaution erforderlich; Versicherung inklusive; Preise ab Fiat Panda 40 € pro Tag, Fiat 500 45 €, VW Polo 52–60 € und 7–9-Sitzer-Vans bis 120 € pro Tag."}}'::jsonb)::text WHERE slug = 'car-rental';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Crazy UFO","description":"Erlebt das Crazy UFO, eine schnelle und aufregende aufblasbare Wasserfahrt, die vor Teneriffa über die Wellen wirbelt, rutscht und hüpft. Diese actiongeladene Gruppenaktivität ist perfekt für Familien und Freunde, die Spaß und Adrenalin auf dem Ozean suchen.","includes":"Sicherheitseinweisung; Schwimmweste; Speedboot-Transfer; Crazy-UFO-Fahrt (25 Minuten); Betreuung durch Instruktor; Versicherung"}}'::jsonb)::text WHERE slug = 'crazy-ufo';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Fly Fish","description":"Genießt den Fly Fish, eine energiegeladene aufblasbare Fahrt, die abhebt, springt und über die Wellen gleitet — ein unvergessliches Fluggefühl. Perfekt für Gruppen verbindet diese Wasseraktivität auf Teneriffa Tempo, Spritzer und Adrenalin in einem aufregenden Erlebnis.","includes":"Dauer insgesamt 45 Minuten; Sicherheitseinweisung; Schwimmweste; Speedboot-Transfer; Fly-Fish-Fahrt (10 Minuten); Betreuung durch Instruktor; Versicherung"}}'::jsonb)::text WHERE slug = 'fly-fish';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Jetski-Abenteuer","description":"Jetski-Abenteuer auf Teneriffa mit schnellen Fahrten entlang der Atlantikküste und atemberaubenden Vulkanblicken. Erlebt eine aufregende Wasseraktivität mit Sonne, Meer und Adrenalin auf der Insel.","includes":"Trivlu-Guide; Privater Transport (Hin- und Rückfahrt); Jetski-Miete; Sicherheitseinweisung & Instruktor; Schwimmweste & Schutzausrüstung; Kraftstoff inklusive; Geführte Küstenfahrt; Wasserdichte Tasche; Drink pro Person"}}'::jsonb)::text WHERE slug = 'jet-ski-adventure';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Loro Parque","description":"Besucht den Loro Parque, eine der berühmtesten Tierattraktionen Teneriffas, mit unglaublichen Tiershows und vielfältigen Arten aus aller Welt. Erkundet wunderschön gestaltete Lebensräume und genießt einen unvergesslichen Tag für alle Altersgruppen.","includes":"Parkeintritt; Tieranlagen; Delfinshow; Orca-Show; Pinguinarium; Botanische Gärten; Ganztagesbesuch"}}'::jsonb)::text WHERE slug = 'loro-parque';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Luxus-Spa-Session","description":"Gönnt euch eine Luxus-Spa-Session für ultimative Entspannung und Regeneration. Genießt Premium-Anwendungen in ruhiger Umgebung für ein belebendes Wellness-Erlebnis.","includes":"Spa-Zugang; Ruhebereich; Sauna; Dampfbad; Handtücher; Premium-Pflegeprodukte"}}'::jsonb)::text WHERE slug = 'luxury-spa-session';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Hochseeangeln","description":"Genießt ein aufregendes Hochseeangel-Erlebnis mit fachkundiger Anleitung und atemberaubendem Blick aufs offene Meer. Dieser 4-stündige Ausflug ist perfekt für alle Könnensstufen und verbindet Abenteuer mit professioneller Betreuung.","includes":"Professioneller Betreuer; Angelausrüstung; Köder; Zubehör; Kalte Getränke. Max. 8 Personen pro Boot."}}'::jsonb)::text WHERE slug = 'ocean-fishing';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Parasailing","description":"Erlebt einen adrenalingeladenen Parasailing-Flug mit atemberaubendem Blick über Ozean und Küste. Genießt eine ruhige Bootsfahrt, bevor ihr für ein einzigartiges 15-minütiges Flugerlebnis abhebt.","includes":"Bootsfahrt (40 Min.); Parasailing-Flug (15 Minuten); Sicherheitsausrüstung; Instruktor-Guide"}}'::jsonb)::text WHERE slug = 'paraceiling';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Privates Boot-Lunch & Strip","description":"Genießt ein privates Lunch auf dem Boot mit Unterhaltung an Bord in entspannter Meeresatmosphäre. Diese besondere Option verbindet Essen auf See mit einer kurzen Live-Performance für einen unvergesslichen Ausflug.","includes":"Lunch auf dem Boot; Privater Rahmen; Oben-ohne-Hostess; 15-minütige Tanzperformance"}}'::jsonb)::text WHERE slug = 'private-boat-lunch-strip';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Private Yachttour / Whale Watching","description":"Genießt eine private Yachttour mit Whale Watching, Schnorcheln und atemberaubendem Meerblick. Dieses 3-stündige Erlebnis verbindet Begegnungen mit Meerestieren mit Essen, Getränken und Entspannung auf See.","includes":"Wal- & Schildkrötensichtungen; Schwimmen (30 Minuten); Schnorcheln; Abwechslungsreiches lokales Essen; Getränke (Wein/Bier – 2 inklusive); Sandwiches; Snacks; Obst\nOptionale Extras: Paella (sehr groß) – 40 €"}}'::jsonb)::text WHERE slug = 'private-yacht-tour-whale-watching';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Quad-Safari-Tour","description":"Erlebt ein aufregendes Quad-Abenteuer durch die raue Landschaft Teneriffas mit malerischen Offroad-Routen und atemberaubenden Aussichtspunkten. Diese geführte Tour verbindet Adrenalin, Natur und unvergessliche Inselkulisse. Einzelquad: 90 EUR / Doppelquad: 95 EUR","includes":"Quad-Miete; Geführte Tour; Sicherheitseinweisung; Helm; Kraftstoff; Aussichtsstopps; Instruktor-Guide. Fahrer braucht gültigen Führerschein; Geeignet für 1 oder 2 Fahrer pro Quad"}}'::jsonb)::text WHERE slug = 'quad-safari-tour';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Siam Park","description":"Besucht den Siam Park auf Teneriffa, seit 10 Jahren in Folge der beste Wasserpark der Welt. Genießt aufregende Rutschen, entspannte Flussfahrten und eine tropische, thailändisch inspirierte Kulisse — perfekt für alle Altersgruppen.","includes":"Parkeintritt; Zugang zu den Rutschen; Lazy River; Wellenbad; Sonnenliegen; Umkleiden"}}'::jsonb)::text WHERE slug = 'siam-park';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Stand-up-Paddling","description":"Genießt Stand-up-Paddling, einen entspannten und spaßigen Wassersport, der weltweit beliebt geworden ist. Leicht zu lernen und für alle Altersgruppen geeignet — eine großartige Art, den Ozean zu erkunden und dabei aktiv zu bleiben.","includes":"Stand-up-Paddle-Board; Paddel; Sicherheitseinweisung; Schwimmweste (falls erforderlich)"}}'::jsonb)::text WHERE slug = 'stand-up-paddle';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Sunset-Bootsparty","description":"Kommt zu einer lebhaften Sunset-Bootsparty mit atemberaubendem Meerblick, Musik und unvergesslicher Stimmung. Dieses Erlebnis verbindet Entspannung und Unterhaltung, während ihr in die goldene Stunde hineinschippert.","includes":"Bootsfahrt; Sonnenuntergangsblick; Musik; Welcome Drink; Partystimmung"}}'::jsonb)::text WHERE slug = 'sunset-boat-party';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Tandem-Gleitschirmfliegen","description":"Erlebt den Nervenkitzel des Tandem-Gleitschirmfliegens über der atemberaubenden Küste und den Vulkanlandschaften Teneriffas mit einem zertifizierten Profipiloten. Genießt einen ruhigen, malerischen Flug mit atemberaubendem Blick auf den Atlantik und den Teide.","includes":"Profipilot; Gleitschirmausrüstung; Sicherheitseinweisung; Versicherung; Hotelabholung (bei einigen Optionen); Flug vom Startplatz am Berg"}}'::jsonb)::text WHERE slug = 'tandem-paragliding';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Teide-Nationalpark-Tour","description":"Erkundet den Teide-Nationalpark mit atemberaubenden Vulkanlandschaften und Panoramablick auf den berühmten Gipfel Teneriffas. Diese geführte Tour bietet eine unvergessliche Reise durch eines der einzigartigsten Naturwunder Spaniens.","includes":"Transport; Geführte Tour; Nationalparkbesuch; Fotostopps"}}'::jsonb)::text WHERE slug = 'teide-national-park-tour';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Thermal-Spa","description":"Entspannt in einem Premium-Thermalzirkel auf Teneriffa mit beheizten Pools, Whirlpools, Saunen und Hydrotherapie-Zonen für die totale Regeneration. Dieses Wellness-Erlebnis ist ideal für Stressabbau, bessere Durchblutung und tiefe Entspannung in ruhiger Luxusumgebung.","includes":"Zugang zum Thermalzirkel; Beheizte Pools; Whirlpool; Sauna; Dampfbad; Ruhebereich; Hydromassage-Düsen; Umkleiden; Handtücher (je nach Tickettyp)"}}'::jsonb)::text WHERE slug = 'thermal-spa';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Whale Watching","description":"Kommt zu einer Whale-Watching-Tour auf einem geräumigen Katamaran mit unglaublichen Begegnungen mit Meerestieren und malerischem Meerblick. Wählt aus flexiblen Dauern und genießt eine komfortable gemeinsame Fahrt mit Essen, Getränken und Schwimmen.","includes":"Walsichtungen; Katamaranfahrt; Essen; Getränke; Schwimmstopp; Hotelabholung.\nGemeinsame Touren, 2 / 3 / 4,5 Stunden Dauer, Kapazität 70–120 Gäste (Freebird, Maxicat)"}}'::jsonb)::text WHERE slug = 'whale-whatching';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"4x4-Offroad-Challenge","description":"Nehmt es direkt vor Krakau mit Schlammpisten und rauem Gelände auf — in einem kraftvollen 4x4-Fahrerlebnis für Adrenalin und Teamwork. Lernt Offroad-Fahrtechniken unter fachkundiger Aufsicht in echter JGA-Abenteuerkulisse.","includes":"4x4-Fahrzeugmiete; Offroad-Fahrerlebnis; Zertifizierter Instruktor; Sicherheitsausrüstung; Rücktransfers; Fahr-Challenge"}}'::jsonb)::text WHERE slug = '4x4-off-road-challenge';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Airsoft-Gefecht","description":"Nehmt in Krakau an einem realistischen Gefechtserlebnis im Militärstil teil — mit Replika-Waffen, taktischen Szenarien und kompletter Kampfausrüstung. Eine energiegeladene JGA-Aktivität, perfekt für kompetitive Gruppen.","includes":"Airsoft-Waffen; 800 BB-Kugeln pro Person; Sicherheitsausrüstung; Taktische Spielszenarien; Zertifizierte Instruktoren; Private Rücktransfers; Lokaler Guide"}}'::jsonb)::text WHERE slug = 'airsoft-combat';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"All-you-can-drink-Stripclub","description":"Genießt VIP-Zugang zu einem der angesagtesten Stripclubs Krakaus mit unbegrenzten Getränken, privater Lounge und Live-Bühnenunterhaltung. Eine beliebte JGA-Wahl für Gruppen, die eine wilde Nacht in Krakau wollen.","includes":"Stripclub-Eintritt; VIP-Lounge-Zugang; 1 Stunde Open Bar; Bühnenshow; Lokaler Guide"}}'::jsonb)::text WHERE slug = 'all-you-can-drink-strip-club';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Axtwerfen","description":"Testet eure Zielsicherheit und tretet gegen die Jungs an — bei einem aufregenden Axtwerf-Erlebnis in Krakau. Eine spaßige und kompetitive JGA-Aktivität, geleitet von professionellen Instruktoren mit echten Äxten und Zielscheiben.","includes":"10 Axtwurf-Runden; Sicherheitsausrüstung; Qualifizierter Instruktor; Wettkampf-Erlebnis; Lokaler Guide"}}'::jsonb)::text WHERE slug = 'axe-throwing-2';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Babes in Oil","description":"Genießt eine wilde private JGA-Show in Krakau mit zwei Performerinnen, Ölwrestling-Unterhaltung, Bier und einer urkomischen Mitmachrunde für den Bräutigam. Eines der unvergesslichsten Erwachsenen-JGA-Erlebnisse Krakaus.","includes":"Privater Raum; Ölwrestling-Show; 2 Bier pro Person; 2 Performerinnen; Mitmachen des Bräutigams; Lokaler Guide"}}'::jsonb)::text WHERE slug = 'babes-in-oil';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Booze-Cruise-Partyboot","description":"Stecht in Krakau auf der Weichsel in See — mit einem privaten Partyboot-Erlebnis, bei dem ihr eure eigenen Getränke mitbringt und an den bekanntesten Vierteln der Stadt vorbeischippert. Eine entspannte und doch spaßige JGA-Aktivität mit toller Aussicht und Partystimmung an Bord.","includes":"Private Flussfahrt; Bootsmiete; Musikanlage (AUX); Eigene Getränke mitbringen; Malerischer Stadtblick; Lokaler Guide"}}'::jsonb)::text WHERE slug = 'booze-cruise-party-boat';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Bowling & Bier","description":"Startet eure JGA-Nacht in Krakau mit einer entspannten Bowling-Session in einer zentralen Location, die freundschaftlichen Wettkampf mit Drinks und toller Atmosphäre verbindet. Das perfekte Warm-up vor dem Nachtleben.","includes":"Bowlingbahn-Miete; Bowlingschuhe; 2 Bier pro Person; Gruppenspiel; Lokaler Guide"}}'::jsonb)::text WHERE slug = 'bowling-beers';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Brauerei-Bierverkostung","description":"Genießt eine richtige JGA-Biersession in Krakau mit Brauereiverkostungen und großen lokalen Bieren in einer aktiven Bierfabrik. Eine perfekte Tagesaktivität für Gruppen, die großartiges Bier und gute Atmosphäre wollen.","includes":"5 Bierproben pro Person; 4 große Biere pro Person; Brauerei-Erlebnis; Lokaler Guide"}}'::jsonb)::text WHERE slug = 'brewery-beer-tasting';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Bubble Football","description":"Spielt in Krakau chaotischen Fünf-gegen-fünf-Fußball in riesigen aufblasbaren Zorbs — eine urkomische und energiegeladene JGA-Aktivität. Hüpft, kracht zusammen und schießt Tore im Wettkampf gegen die Jungs.","includes":"Bubble-Football-Spiel; Zorb-Anzüge; Ausrüstung; Indoor-/Outdoor-Platz; Private Rücktransfers; Lokaler Guide"}}'::jsonb)::text WHERE slug = 'bubble-football-2';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Casino VIP","description":"Genießt eine stilvolle Casino-Nacht in Krakau mit Spielchips, Drinks und VIP-Service in einem der Top-Casinos der Stadt. Eine elegante JGA-Option mit Roulette, Karten und Nachtleben-Atmosphäre.","includes":"Casino-Eintritt; Spielchips; 2 Drinks pro Person; VIP-Erlebnis; Lokaler Guide"}}'::jsonb)::text WHERE slug = 'casino-vip';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Kommunismus-Tour","description":"Reist zurück in der Zeit mit einer geführten Tour durch die kommunistische Ära Krakaus — mit historischen Vierteln, traditionellem Essen, Wodka-Shots und lokaler Kultur aus Polens sowjetischer Vergangenheit. Eine einzigartige JGA-Aktivität, die Sightseeing mit Drinks und authentischen Erlebnissen verbindet.","includes":"Privater Hin- und Rücktransport; Wodka-Shots; Traditionelle Mahlzeit; Sightseeing-Tour; Lizenzierter Guide; Besuch des kommunistischen Viertels"}}'::jsonb)::text WHERE slug = 'communist-tour';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Dinner-Reservierung","description":"Sichert euch ohne Aufwand einen Tisch in einem Top-Restaurant in Krakau — vorab organisiertes, JGA-freundliches Essen vor einer großen Nacht. Perfekt für Gruppen, die einen reibungslosen Start in den Abend wollen.","includes":"Tischreservierung; Restaurantbuchung; Lokaler Guide; Dinner-Organisation"}}'::jsonb)::text WHERE slug = 'dinner-reservations';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Betrunkene-Braut-Prank","description":"Schockt den Bräutigam mit einem urkomischen Fake-Hochzeits-Prank in Krakau: Eine „betrunkene Braut“ folgt ihm und behauptet, sie hätten letzte Nacht geheiratet. Ein lustiges JGA-Extra, das garantiert den Bräutigam blamiert und die ganze Gruppe unterhält.","includes":"Fake-Braut-Schauspielerin; 3 Shots für den Bräutigam; Hochzeits-Prank-Szenario; Handschellen-Prank; Lokaler Guide"}}'::jsonb)::text WHERE slug = 'drunk-bride-prank';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Escape Room","description":"Testet Teamwork und Problemlösungsfähigkeiten in einem thematischen Escape Room in Krakau. Löst gemeinsam Rätsel und entkommt innerhalb des Zeitlimits — eine spaßige, immersive JGA-Aktivität.","includes":"Escape-Room-Spiel; 60 Minuten Spielzeit; Spielleiter; Privates Erlebnis; Rätsel-Challenge"}}'::jsonb)::text WHERE slug = 'escape-room';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Fußballspiel","description":"Genießt eine kompetitive Fußball-Session in Krakau auf einem Indoor- oder Outdoor-Platz — perfekt für JGA-Gruppen, die etwas Action am Tag und freundschaftliche Rivalität wollen.","includes":"Platzmiete; Fußballausrüstung; Umkleiden; Duschen; Mineralwasser; Lokaler Guide"}}'::jsonb)::text WHERE slug = 'football-match';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Indoor-Go-Kart","description":"Tretet in Krakau gegen die Jungs in einer Highspeed-Go-Kart-Challenge an — mit Zeitläufen, Qualifying und einer finalen Meisterschaftsrunde. Eine kompetitive JGA-Aktivität, perfekt für Adrenalin und Angeberrechte.","includes":"3 Rennrunden; Kart-Ausrüstung; Schutzausrüstung; Professioneller Instruktor; Wettkampfformat; Rücktransfers"}}'::jsonb)::text WHERE slug = 'indoor-go-karting';
UPDATE activities SET translations = (COALESCE(translations::jsonb, '{}'::jsonb) || '{"de":{"name":"Kalaschnikow-Schießen","description":"Nehmt direkt vor Krakau ein adrenalingeladenes Schießerlebnis in Angriff — mit starken Schusswaffen wie der legendären AK-47, Glock-Pistole, Flinte und Trainingsgewehr. Eine Pflicht-JGA-Aktivität für Gruppen, die Action und Wettkampf suchen.","includes":"AK-47-Schießen; Glock-Pistole; Flinten-Erlebnis; Trainingsgewehr; Sicherheitsausrüstung; Qualifizierter Instruktor; Rücktransfers; Lokaler Guide"}}'::jsonb)::text WHERE slug = 'kalashnikov-shooting';
